using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probes without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? resolvedInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {resolvedInfo!.Type.Name}");
}

// Now demonstrate a case where metadata is NOT available.
// Use a custom resolver that only knows about Person.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Reject anything that isn't Person
            if (ti.Type != typeof(Person))
                ti.CreateObject = null; // still resolves, so let's use a blank resolver instead
        })
};

// A truly restricted resolver: only resolves Person
var restrictedResolver = JsonTypeInfoResolver.Combine(
    new PersonOnlyResolver());

var restrictedOptions = new JsonSerializerOptions { TypeInfoResolver = restrictedResolver };

if (restrictedOptions.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? orderInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Order> succeeded (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Order> → not available (no exception thrown)");
}

Console.WriteLine("Done.");

